{
  "claims": [
    {
      "claim_id": "ISS-001",
      "claim_text": "Motor proteins (kinesin and/or dynein) are the actors that move vesicles along microtubules, converting ATP hydrolysis into mechanical stepping.",
      "entailment_status": "PARTIALLY_SUPPORTED",
      "biological_scope": "Eukaryotic intracellular transport; microtubule-based vesicle motility; motor protein families (kinesin superfamily, cytoplasmic dynein).",
      "support": [
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "Microtubules (MTs) are built from α-/β-tubulin dimers and used as tracks by kinesin and dynein motors to transport a variety of cargos, such as mRNAs, proteins, and organelles, within the cell."
        },
        {
          "evidence_id": "E_3717dae1f63f",
          "location": "abstract",
          "quote": "Tau binds microtubules cooperatively to form cohesive envelopes, which are thought to control access to the microtubule lattice and regulate the activity of motor proteins and other MAPs."
        }
      ],
      "reason": "Sources state that kinesin and dynein motors use microtubules as tracks to transport cargo including organelles, and mention motor protein activity regulation. However, no source explicitly states that ATP hydrolysis is converted into mechanical stepping, nor specifically identifies vesicles as the cargo in the quoted passages. The core motor-identity and track-use claim is supported, but the ATP-stepping mechanism is not entailed by the provided excerpts."
    },
    {
      "claim_id": "ISS-002",
      "claim_text": "Vesicle motility along microtubule tracks depends causally on motor protein activity (ATP-dependent stepping), not merely on microtubule presence.",
      "entailment_status": "INSUFFICIENT_EVIDENCE",
      "biological_scope": "Mechanistic cell biology; in vitro and in vivo motor-dependent transport assays; axonemal and axonal transport.",
      "support": [
        {
          "evidence_id": "E_3717dae1f63f",
          "location": "abstract",
          "quote": "Tau weakly inhibits KIF5C motility, but strongly inhibits KIF1A. Hyperphosphorylation reduces KIF5C inhibition but increases KIF1A inhibition by decreasing processivity and accelerating detachment."
        },
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "two kinesin-1-dependent processes, the precise localization of Staufen and the fast, bidirectional ooplasmic streaming, depend on TTLL5 , too, suggesting a causative pathway."
        }
      ],
      "reason": "Sources provide indirect evidence of motor-dependent processes (kinesin-1-dependent ooplasmic streaming, tau regulation of lysosome transport via KIF5C/KIF1A modulation), but no passage explicitly demonstrates causal dependence of vesicle motility on motor protein ATP-dependent stepping versus mere microtubule presence. The required claim is not directly entailed."
    },
    {
      "claim_id": "ISS-003",
      "claim_text": "Single-vesicle tracking or live imaging demonstrates vesicles remain associated with microtubule tracks during defined transport intervals.",
      "entailment_status": "INSUFFICIENT_EVIDENCE",
      "biological_scope": "Live-cell imaging and single-particle tracking of vesicle-microtubule interactions; temporal persistence of track association.",
      "support": [
        {
          "evidence_id": "E_3717dae1f63f",
          "location": "abstract",
          "quote": "Using tau phospho-variants in vitro and in live neurons, we show that tau hyperphosphorylation disrupts cooperative microtubule binding and dysregulates lysosome transport."
        }
      ],
      "reason": "One source mentions live neurons and lysosome transport, but does not describe single-vesicle tracking or temporal persistence of vesicle association with microtubule tracks during defined intervals. No source provides the required tracking/persistence evidence."
    },
    {
      "claim_id": "ISS-004",
      "claim_text": "Microtubules function as structural tracks (polar filaments) that enable transport; track provision is a structural capability rather than a temporally bounded process.",
      "entailment_status": "PARTIALLY_SUPPORTED",
      "biological_scope": "Microtubule structure and polarity; cytoskeletal organization; distinction between structural capability and process.",
      "support": [
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "Microtubules (MTs) are built from α-/β-tubulin dimers and used as tracks by kinesin and dynein motors to transport a variety of cargos, such as mRNAs, proteins, and organelles, within the cell."
        }
      ],
      "reason": "The source states microtubules are used as tracks by motors to transport cargo, supporting the structural track function. However, no source explicitly characterizes track provision as a structural capability rather than a temporally bounded process, nor discusses polarity in the quoted passage. The key distinction required by the claim is not entailed."
    },
    {
      "claim_id": "ISS-005",
      "claim_text": "Vesicles are membrane-bound cargo carriers whose transport occurs specifically along microtubules (distinct from general cytoplasm streaming).",
      "entailment_status": "PARTIALLY_SUPPORTED",
      "biological_scope": "Vesicle definition (membrane-bound organelles), cargo transport, microtubule-specific transport vs general cytoplasmic movement.",
      "support": [
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "Microtubules (MTs) are built from α-/β-tubulin dimers and used as tracks by kinesin and dynein motors to transport a variety of cargos, such as mRNAs, proteins, and organelles, within the cell."
        }
      ],
      "reason": "The source lists organelles among cargos transported along microtubule tracks, supporting that organelles (which include vesicles) are cargo. However, it does not define vesicles as membrane-bound, nor explicitly distinguish microtubule-specific transport from general cytoplasm streaming. The required specificity and definition are not fully entailed."
    },
    {
      "claim_id": "ISS-006",
      "claim_text": "The topic scope requires motor protein identity/mechanism; if evidence is limited, scope must be explicitly narrowed with stated non-claims.",
      "entailment_status": "OUT_OF_SCOPE",
      "biological_scope": "Scope definition for teaching model; motor-protein-dependent transport mechanism; organism and cell-type specificity.",
      "support": [],
      "reason": "This is a meta-claim about scope definition and teaching-model requirements, not a biological mechanism claim addressed by the provided sources. Sources do not discuss scope requirements or non-claims."
    },
    {
      "claim_id": "ISS-007",
      "claim_text": "Kinesins generally drive anterograde/plus-end-directed transport; cytoplasmic dynein drives retrograde/minus-end-directed transport; specificity varies by organism/cell type.",
      "entailment_status": "INSUFFICIENT_EVIDENCE",
      "biological_scope": "Motor directionality conventions; plus-end vs minus-end; neuron axon vs other cell types; organism variation.",
      "support": [
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "In the nervous system, a mutation of TTLL5 that inactivates its enzymatic activity decreases the pausing of anterograde axonal transport of mitochondria."
        }
      ],
      "reason": "The source mentions anterograde axonal transport but does not state kinesin drives anterograde or dynein drives retrograde, nor plus-end/minus-end directionality. No directionality conventions or organism-specific variation are entailed."
    },
    {
      "claim_id": "STATE_MODEL_MIGRATION",
      "claim_text": "Initial states for vesicle (position, motor association) and microtubule (polarity, availability) must be evidenced; motor protein and ATP states are necessary producers for transport.",
      "entailment_status": "INSUFFICIENT_EVIDENCE",
      "biological_scope": "State modeling of intracellular transport; initial conditions; motor-vesicle-microtubule association states; ATP availability.",
      "support": [
        {
          "evidence_id": "E_3717dae1f63f",
          "location": "abstract",
          "quote": "Tau binds microtubules cooperatively to form cohesive envelopes, which are thought to control access to the microtubule lattice and regulate the activity of motor proteins and other MAPs."
        }
      ],
      "reason": "The source discusses motor protein regulation and microtubule access, but does not provide evidence for initial-state requirements (vesicle position, motor association, microtubule polarity/availability) or ATP as a necessary producer state. The state-modeling claim is not entailed."
    }
  ],
  "decision": "FAIL"
}
